Translate("ptBR", "powderfuse-port", {
	title = "Powderfuse Port",
	aliases = { "Powderfuse" },
	sections = {
		{
			title = "Resumo",
			text = [=[Powderfuse Port é um porto goblin na costa leste dos {link:riverglades}Riverglades{/link}, e não pertence a lado nenhum senão ao seu próprio. Os goblins Powderfuse o construíram. Navios do {link:steamwheedle-cartel}Cartel Bondebico{/link} partem de seu cais, atravessando o mar até {link:tanaris}Tanaris{/link}. O Mestre do Cais Whizzbuzz cuida das docas, e o mestre engenheiro {link:melbin-powderfuse}Melbin Powderfuse{/link} ensina seu ofício na cidade. O porto tem banqueiros, mercadores de muitos ramos, pescadores e um mercado de bens raros. Brutamontes goblins mantêm a ordem em suas ruas.]=],
		},
	},
})

Translate("ptBR", "sunnyglade", {
	title = "Sunnyglade",
	sections = {
		{
			title = "Resumo",
			text = [=[Sunnyglade foi outrora uma cidade rica e próspera do reino. Na {link:first-war}Primeira Guerra{/link}, os orcs caíram sobre ela. Pouparam uma torre, pois queriam aprender como a magia humana era feita, e arrastaram os sobreviventes como escravos. Soldados do rei libertaram os cativos e reconstruíram a cidade. Não durou. Sunnyglade jaz agora em ruínas, e os cultistas do {link:twilight-s-hammer}Martelo do Crepúsculo{/link} a tomaram para si. Sua velha torre de magos ainda se ergue acima das casas quebradas.]=],
		},
	},
})

Translate("ptBR", "bolder-ok", {
	title = "Bolder'ok",
	sections = {
		{
			title = "Resumo",
			text = [=[Bolder'ok é uma cidade de ogros no norte dos {link:riverglades}Riverglades{/link}. Brutamontes e magos vivem ali, e um mestre de sangue chamado {link:chub-chob}Chub'chob{/link} os governa. Gronok, o Açougueiro, e outros ogros de nome são encontrados na cidade e em seus arredores. Os ogros de Bolder'ok podem fazer parte de uma ameaça maior: um clã de ogros cujo poder cresceu nas clareiras, e cuja maior fortaleza é {red:krol-dok-stronghold}Krol'dok{/red}.]=],
